use vstd::prelude::*;

verus! {

    // Insert `delimiter` between every pair of consecutive elements of `numbers`.
    // If `numbers.len() <= 1`, returns `numbers` unchanged.
    //
    // Specification (in terms of the “model sequence” `@`):
    //   Let n = numbers.len().
    //   If n ≤ 1, then result@ == numbers@.
    //   Otherwise:
    //     result.len() == 2*n − 1, and
    //     for all j < result.len():
    //       if j%2 == 0 then result@[j] == numbers@[j/2]
    //       else               result@[j] == delimiter
    //
    fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> (result: Vec<i8>)
        ensures
            let n = numbers.len();
            if n <= 1 {
                result@ == numbers@
            } else {
                result.len() == 2*n - 1 &&
                forall |j: usize| j < result.len() ==>
                    if j % 2 == 0 {
                        result@[j] == numbers@[j / 2]
                    } else {
                        result@[j] == delimiter
                    }
            }
    {
        let n = numbers.len();
        if n <= 1 {
            // Nothing to do
            return numbers;
        }

        let mut result: Vec<i8> = Vec::new();
        // reserve exact capacity so we never reallocate
        result.reserve(2 * n - 1);

        let mut i: usize = 0;
        while i < n
            invariant
                // We have processed exactly `i` input elements
                i <= n,
                // and pushed exactly 2*i elements so far
                result.len() == 2 * i,
                // and the model sequence property holds for all pushed entries
                forall |j: usize| j < result.len() ==>
                    if j % 2 == 0 {
                        result@[j] == numbers@[j / 2]
                    } else {
                        result@[j] == delimiter
                    },
            decreases n - i,
        {
            // push the i-th element
            let x = numbers[i];
            result.push(x);
            // now result@[2*i] == x == numbers@[i]
            assert(result@[2 * i] == numbers@[i]);

            // if not the last input, push a delimiter
            if i + 1 < n {
                result.push(delimiter);
                // now result@[2*i + 1] == delimiter
                assert(result@[2 * i + 1] == delimiter);
            }

            i += 1;
        }

        result
    }

}

